import axios from 'axios';

const API_BASE_URL =
  process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

const api = axios.create({
  baseURL: API_BASE_URL,
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('access_token');

  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  return config;
});

export const getApiErrorMessage = (
  error,
  fallback = 'Something went wrong.'
) => {
  const detail = error?.response?.data?.detail;

  if (Array.isArray(detail)) {
    return detail
      .map((item) => item?.msg || item)
      .filter(Boolean)
      .join(', ');
  }

  return (
    detail ||
    error?.response?.data?.message ||
    error?.message ||
    fallback
  );
};

// ==========================================
// GET ALL ENROLLMENTS - ADMIN ONLY
// ==========================================
export const getEnrollments = async (
  skip = 0,
  limit = 100
) => {
  const response = await api.get(
    '/api/enrollments/',
    {
      params: {
        skip,
        limit,
      },
    }
  );

  return response.data;
};


// ==========================================
// GET SINGLE ENROLLMENT - ADMIN ONLY
// ==========================================
export const getEnrollment = async (
  enrollmentId
) => {
  const response = await api.get(
    `/api/enrollments/${enrollmentId}`
  );

  return response.data;
};


// ==========================================
// CREATE ENROLLMENT - PUBLIC
// ==========================================
export const createEnrollment = async (
  data
) => {
  const response = await api.post(
    '/api/enrollments/',
    data
  );

  return response.data;
};


// ==========================================
// UPDATE ENROLLMENT STATUS - ADMIN ONLY
// ==========================================
export const updateEnrollmentStatus = async (
  enrollmentId,
  status
) => {
  const response = await api.patch(
    `/api/enrollments/${enrollmentId}/status`,
    {
      status,
    }
  );

  return response.data;
};


// ==========================================
// DELETE ENROLLMENT - ADMIN ONLY
// ==========================================
export const deleteEnrollment = async (
  enrollmentId
) => {
  const response = await api.delete(
    `/api/enrollments/${enrollmentId}`
  );

  return response.data;
};


// ==========================================
// ENROLLMENTS API
// ==========================================
export const enrollmentsAPI = {
  getAll: getEnrollments,
  getOne: getEnrollment,
  create: createEnrollment,
  updateStatus: updateEnrollmentStatus,
  delete: deleteEnrollment,
};

export default api;
